/**
 * Python/TypeScript parity: every output recorded from the Python package in
 * tests/parity/corpus.json.gz (generated by tests/parity/generate.py) must be
 * reproduced exactly: repaired schemas, every change and issue (with messages),
 * ok flags, restored arguments, tool name maps and sanitized names.
 */

import { readFileSync } from "node:fs";
import { gunzipSync } from "node:zlib";
import { describe, expect, it } from "vitest";
import { type Json, restoreArguments, sanitizeName, transformSchema, transformTools } from "../src/index.js";

interface IssueRecord {
  code: string;
  path: string;
  message: string;
  severity: string;
  fixable: boolean;
  lossy: boolean;
  tool: string | null;
}
interface SchemaCase {
  input: Json;
  target: string;
  schema: Json;
  changes: IssueRecord[];
  issues: IssueRecord[];
  ok: boolean;
  restore: { args: Json; out: Json }[];
}
interface ToolCase {
  input: Json[];
  target: string;
  tools: Json[];
  changes: IssueRecord[];
  issues: IssueRecord[];
  name_map: Record<string, string>;
  ok: boolean;
}

const corpus = JSON.parse(
  gunzipSync(readFileSync(new URL("../../tests/parity/corpus.json.gz", import.meta.url))).toString("utf8"),
) as {
  schemas: SchemaCase[];
  tools: ToolCase[];
  names: { name: string; target: string; out: string }[];
};

describe("parity with the Python package", () => {
  it("has a non-trivial corpus", () => {
    expect(corpus.schemas.length).toBeGreaterThanOrEqual(3000);
    expect(corpus.tools.length).toBeGreaterThanOrEqual(10);
  });

  it.each(corpus.schemas.map((c, i) => [i, c] as const))("schema case %i", (_i, c) => {
    const before = JSON.stringify(c.input);
    const result = transformSchema(c.input, c.target);
    expect(JSON.stringify(c.input)).toBe(before); // never mutated
    expect(result.schema).toEqual(c.schema);
    expect(result.changes).toEqual(c.changes);
    expect(result.issues).toEqual(c.issues);
    expect(result.ok).toBe(c.ok);
    for (const r of c.restore) {
      expect(restoreArguments(r.args, c.input, c.target)).toEqual(r.out);
    }
  });

  it.each(corpus.tools.map((c, i) => [i, c.target, c] as const))("tool case %i (%s)", (_i, _t, c) => {
    const result = transformTools(c.input, c.target);
    expect(result.tools).toEqual(c.tools);
    expect(result.changes).toEqual(c.changes);
    expect(result.issues).toEqual(c.issues);
    expect(result.nameMap).toEqual(c.name_map);
    expect(result.ok).toBe(c.ok);
  });

  it.each(corpus.names.map((c) => [c.name, c.target, c.out] as const))(
    "sanitizeName(%j, %s)",
    (name, target, out) => {
      expect(sanitizeName(name, target)).toBe(out);
    },
  );
});
